{
  "summary": "Renewal request from Acme Cloud Services with a 12% price increase needs to be evaluated against the current contract terms, SLA performance, and any credits owed before drafting a response.",
  "reply_type": "vendor_email",
  "steps": [
    {
      "id": 1,
      "agent": "retriever",
      "task": "List and read the current Acme Cloud Services contract to find pricing, term end date, renewal clauses, and SLA commitments; check performance/invoice documents for any SLA misses in the current term and run the SLA credit calculator to determine any credits owed; if any amounts are in USD or another foreign currency, use the currency converter to express them in our reporting currency.",
      "why": "The executor needs the exact contract terms, current pricing, SLA performance history, and any owed credits to draft an informed response to the 12% price increase."
    },
    {
      "id": 2,
      "agent": "executor",
      "task": "Draft a vendor email response to Acme Cloud Services addressing the renewal request: acknowledge the contract end date, reference actual SLA performance and any credits owed (netting them against the proposed increase if applicable), and propose a counter-offer or acceptance terms based on the gathered facts.",
      "why": "The executor must synthesize the retrieved contract, SLA, and financial facts into a clear, complete reply for human review and approval."
    }
  ],
  "escalate": null
}
